('verified-br-itambe-minas-90-white','Camisa Itambé Minas Vôlei Jogo Masculina Branca Especial 90 Anos','Camisa masculina oficial de jogo Itambé Minas, edição 90 anos (temporada 2025), 90% poliéster e 10% elastano. Preço sem personalização; tamanhos P, M, G, GG, EG e EGG listados na Nakal em 23/11/2026.','Nakal','Vestuário','Vôlei',199.90,NULL,'https://images.tcdn.com.br/img/img_prod/735439/camisa_itambe_minas_jogo_masc_branca_especial_90_anos_1257_1_3275fabe607abe75f8a796099a1c277c.jpg','https://www.nakal.com.br/equipes-profissionais/itambe-minas-volei/camisa-itambe-minas-jogo-masc-branca-especial-90-anos',ARRAY['https://images.tcdn.com.br/img/img_prod/735439/camisa_itambe_minas_jogo_masc_branca_especial_90_anos_1257_1_3275fabe607abe75f8a796099a1c277c.jpg','https://images.tcdn.com.br/img/img_prod/735439/camisa_itambe_minas_jogo_masc_branca_especial_90_anos_1257_2_dc052754f732a1598e7ec5b72f2d883d.jpg']::text[],ARRAY['P','M','G','GG','EG','EGG']::text[],'superliga-brasil-masculina-2026-27:itambe-minas',true),
('verified-br-kto-minas-90-royal','Regata KTO Minas Basquete Jogo Masculina Azul Royal Especial 90 Anos','Regata oficial masculina de jogo KTO Minas Basquete royal (temporada 2025, edição 90 anos), 100% poliéster. Preço sem personalização; tamanhos P, M, G e GG listados na Nakal em 23/11/2026.','Nakal','Vestuário','Basquete',199.90,NULL,'https://images.tcdn.com.br/img/img_prod/735439/camisa_kto_minas_basquete_jogo_masc_royal_especial_90_anos_1263_1_6d7faa15677cf68e25e6e37347eed54a.jpg','https://www.nakal.com.br/equipes-profissionais/kto-minas-basquete/camisa-kto-minas-basquete-jogo-masc-royal-especial-90-anos',ARRAY['https://images.tcdn.com.br/img/img_prod/735439/camisa_kto_minas_basquete_jogo_masc_royal_especial_90_anos_1263_1_6d7faa15677cf68e25e6e37347eed54a.jpg','https://images.tcdn.com.br/img/img_prod/735439/camisa_kto_minas_basquete_jogo_masc_royal_especial_90_anos_1263_2_85c36b4cd2103fc4e9588edd96c7ad64.jpg']::text[],ARRAY['P','M','G','GG']::text[],'nbb-brasil-2026-27:minas-tenis-clube',true)
) AS v(id,title,description,store_name,category,sport,price,original_price,image_url,source_url,image_urls,variant_options,team_id,is_active)
WHERE EXISTS(SELECT 1 FROM public.catalog_teams t WHERE t.id=v.team_id)
AND NOT EXISTS(SELECT 1 FROM public.external_offers o WHERE o.id=v.id OR o.source_url=v.source_url)
ON CONFLICT (id) DO NOTHING;
